  'about.bookshopLeadIn': "Kitapçımızı işleten aynı küçük işletme tarafından yapıldı:",
  "about.eyebrow": "Luminous StockHaven Hakkında",
  "about.pageTitle": "Luminous StockHaven — Hakkımızda",
  "about.founderHeading": "📖 Kurucu Hakkında",
  "about.founder.p1": "Merhaba, ben Concepcion, Luminous StockHaven’ın kurucusuyum.",
  "about.founder.p2": "Büyük bir teknoloji şirketinden gelmiyorum ve bir şirket ofisinde oturmuyorum. Tıpkı sizin gibi küçük bir perakende sahibiyim. Kitaplar ve kitap severler için el yapımı aksesuarlar konusunda uzmanlaşmış beş e-ticaret mağazası yönetiyorum.\nBirçok bağımsız perakendeci gibi, birden fazla konumdaki envanteri yönetmeye, yayınevlerinin ISBN’lerini kendi el yapımı SKU’larımın yanında takip etmeye ve tedarikçi siparişlerini hantal tablolarla halletmeye çalışırken bir kırılma noktasına geldim. Bana yardım edecek bir uygulama aradığımda altı farklı seçenek denedim. Her biri ya tamamen eksikti, ya inanılmaz derecede karışıktı ya da fırsatçıydı — temel araçlar için ayda yüzlerce dolar istiyorlardı.",
  "about.founder.p3": "Bağımsız üreticileri sömüren bir sektörden bıkıp kendi çözümümü oluşturmaya karar verdim. Luminous StockHaven’ı, kendi işlerimi temiz, verimli ve tam bir gönül rahatlığıyla yürütmek için zorunluluktan inşa ettim.",
  "about.founder.p4": "Bu platformu halka dürüst ve uygun bir fiyatla açmaya karar verdim, çünkü her küçük işletme sahibi, gelirini riske atmadan gerçekten işe yarayan araçları hak ediyor. Bağımsız bir işletmeyiz, topluluğumuzu şiddetle koruyoruz ve bir perakendeci tarafından perakendeciler için inşa edildik.",
  "notice.ariaLabel": "Ticari marka ve telif hakkı bildirimi",
  "notice.heading": "🛡️ Perakendeciler İçin İnşa Edildi, Kurumsal Akbabalar İçin Paha Biçilemez",
  "notice.intro": "Bu uygulamayı, 5 mağaza işlettiğim ve yüzlerce dolarlık kafa karıştırıcı yazılımlarla kazıklanmaktan bıktığım için inşa ettim. Bu uygulama; bağımsız sanatçıları, zanaatkârları, kitapçıları ve yerel dükkânları korumak için inşa edildi.",
  "notice.legalHeading": "RAKİPLERE VE TAKLİTÇİLERE YASAL BİLDİRİM:",
  "notice.legalBody": "Pazarı aktif olarak izliyoruz. Platformumuzu kazımaya, bize özgü iş akışlarımızı klonlamaya veya fikri mülkiyetimizi ihlal etmeye yönelik her girişim, derhal ve agresif yasal işlemlerle karşılanacaktır.",
  "notice.acquisitionHeading": "SATIN ALMA FİRMALARINA VE ARACILARA:",
  "notice.acquisitionBody": "Bana e-posta atmayın. Bana özel mesaj göndermeyin. Bana 'stratejik bir çıkış' teklif etmeyin. Binler, milyonlar, milyarlar veya trilyonlar teklif edebilirsiniz — cevap Hayır. Bu uygulamayı, perakendeci arkadaşlarımın fiyatlarını yükseltmek için satın alamayacaksınız. Her istenmeyen satın alma e-postası anında spam olarak işaretlenecek ve alan adınız platformumuzdan kalıcı olarak engellenecektir. Nefesinizi boşa harcamayın.",
