  "plans.intro": "Hangi planı seçerseniz seçin tek hesap — Business en fazla beş işletmeyi kapsar. Fiyatlar ABD doları cinsinden aylıktır ve uygun yeni web sitesi müşterileri Essentials ve Business genelinde bir adet yedi günlük deneme alabilir. Mevcut bir Essentials aboneliğini Business'a yükseltmek denemeyi yeniden başlatmaz veya başka bir ücretsiz deneme oluşturmaz. Web sitesi plan fiyatları, varsa geçerli vergilerden öncedir. Tam ücretiniz, bir aboneliğe yetki vermeden önce gösterilecektir.",
