  "settings.businesses.createDescription": "Bu, kendi ürünleri, konumları, tedarikçileri ve satın alma kayıtları olan ayrı bir işletme oluşturur. Mevcut işletmeler değiştirilmez. Ücretsiz lansman öncesi çalışma alanları başka bir ücretsiz deneme başlatmaz.",
