  "settings.details.taxModeHint": "Sabit, her yeni siparişte sizin oranınızı kullanır. Otomatik, eyalet siparişe yazıldığı anda yeni bir siparişin vergisini müşterinin eyalet temel oranıyla doldurur ve eyalet değişirse yeniden doldurur. Bunlar eyalet temel oranlarıdır — yerel vergiler eklenebilir. Eyaleti olmayan veya ABD dışından bir sipariş, yukarıdaki sabit oranınızı kullanır.",
