  "settings.logout": "Çıkış yap",
  "settings.pastDue.body": "Son ödemeniz gerçekleşmedi. Başarısız ödemeden itibaren 14 gün boyunca, siz düzeltirken tam kullanımı korursunuz. Düzeltilmezse abonelik iptal edilir, çalışma alanı 15 gün boyunca yalnızca görüntüleme moduna geçer ve ardından hesap ve tüm bilgileri silinir. Silinmeden önce herhangi bir zamanda ödeme yapmak her şeyi geri getirir. Ne yapacağınızdan emin değilseniz theluminousbookshop@outlook.com adresinden destek ile iletişime geçin.",
