  "settings.security.description": "Yedek anahtarlarınızı İHTİYACINIZ OLMADAN ÖNCE kurunuz: hesap e-postanıza erişimi hiç kaybederseniz, mağazanızı geri alma yolunuz onlardır.",
  "settings.security.genericError": "Bir şeyler ters gitti. Lütfen tekrar deneyiniz.",
