  "settings.security.backupCodesTitle": "Yedek kodlar",
  "settings.security.backupCodesDesc": "Tek kullanımlık yedek anahtarlar. Onları yazdırınız veya yazınız ve güvenli bir yerde tutunuz — her biri e-postanızı kaybederseniz sizi bir kez geri getirebilir.",
  "settings.security.codesRemaining": "Kalan kullanılmamış yedek kod: {count}",
  "settings.security.generateCodes": "Yedek kodlar oluştur",
