  "settings.security.codesOnceWarning": "Bu kodlar yalnızca bir kez gösterilir — yalnızca karıştırılmış bir kopyayı tutarız, böylece biz bile onları tekrar gösteremeyiz. Yeni bir set oluşturmak her eski kodu iptal eder.",
