  "settings.security.backupEmailDesc": "Kontrol ettiğiniz ikinci bir e-posta adresi. Ana e-postanız hiç ulaşılamaz olursa, bunun yerine buraya bir kurtarma kodu gönderilebilir.",
  "settings.security.backupEmailLabel": "Yedek e-posta adresi",
