  "training.lessons.owner-shipping-labels.step1": "Yazdırma Merkezi her iki planda da bir Kargo etiketi stili taşır: bir müşteri siparişi seçin ve alıcının adı ve adresiyle, gönderen olarak işletmenizle bir 4×6 etiket yazdırın.",
  "training.lessons.owner-shipping-labels.step2": "Etiket, her müşteri belgesi gibi beyaz etiketlidir: yalnızca işletmenizin adını taşır — bu uygulamanın adını asla —, böylece mağazanızdan gelen bir paket gerçekten mağazanızdan gelmiş gibi görünür.",
  "training.lessons.owner-shipping-labels.step3": "Müşterinin adresi, son siparişinden sonra 90 gün boyunca siparişleriyle birlikte tutulur ve etiket, varsa siparişin kayıtlı adresinden başlar; tek seferlik bir etiket için yazdırma sırasında yazılan bir adres geri kaydedilmez. Ad yine de siparişten doldurulur, böylece etiket evraklarla eşleşir.",
  "training.lessons.owner-shipping-labels.step4": "Etiket, her etiketle aynı dört bağlantıdan yazdırılır — Bluetooth, Wi-Fi, Ethernet ve USB — ve 4×6 termal yazıcı onun standart boyutudur.",
  "training.lessons.owner-shipping-labels.step5": "Posta ücretini bunun yerine taşıyıcıdan mı satın aldınız? Aynı bölümde taşıyıcının etiket dosyasını — PDF, PNG veya JPG — yükleyebilirsiniz ve siparişte sonsuza dek kayıtlı kalır: kaydınız, bir şey olursa elinizin altında. Gerçek 4×6 boyutunda yazdırılır. Uygulama asla posta ücreti satmaz, bu yüzden taşıyıcının fiyatı tek fiyattır — ve her zaman doğru fiyattır.",
  "training.lessons.owner-shipping-labels.title": "Müşteri siparişleri için kargo etiketleri",
  "training.lessons.print-shipping-label.step1": "Bir sipariş gönderilmeye hazır olduğunda Yazdırma Merkezi’ni açın, Kargo etiketi stilini seçin ve sonra müşteri siparişini seçin. Alıcının adı siparişten doldurulur.",
  "training.lessons.print-shipping-label.step2": "Paketin gideceği adresi kontrol edin. Sipariş müşterinin adresini taşıdığında — son siparişinden sonra 90 gün tutulur — sizin için doldurulur; yazdırma sırasında yazdığınız bir adres geri kaydedilmez, bu yüzden yazdırmadan önce posta kodunu ve son satırı dikkatle kontrol edin.",
  "training.lessons.print-shipping-label.step3": "İşletmenizin adı, gönderen olarak üstte yazdırılır. Adresinizin de etikette olmasını isterseniz gönderen adresi kutusuna yazın; görünmesini istemezseniz boş bırakın.",
  "training.lessons.print-shipping-label.step4": "4×6 etikete yazdırın — termal etiket yazıcısı alışılmış seçimdir — ya da tarayıcının yazdır düğmesiyle herhangi bir yazıcıda. Etiketi paketin üzerine, bir kenardan katlanmayacak şekilde düz yapıştırın.",
  "training.lessons.print-shipping-label.step5": "Posta ücreti taşıyıcıdan satın alındıysa, bunun yerine onların etiket dosyasını siparişe kaydedin: taşıyıcının size verdiği PDF, PNG veya JPG dosyasını Taşıyıcınızın etiketi bölümüne yükleyin. Kaydınız olarak siparişte kalır ve gerçek 4×6 boyutunda yazdırılır — ve uygulamının kendi adres etiketi, kullanmayı tercih ettiğinizde her zaman oradadır.",
  "training.lessons.print-shipping-label.title": "Kargo etiketi yazdırın",
