  "pos.stripeTerminal.help": "Stripe Terminal kendi Stripe hesabınızda çalışır. Stripe panonuzda bu uygulama için bir webhook uç noktası kaydediniz, ardından hesap kimliğinizi ve o uç noktanın imza sırrını buraya yapıştırınız.",
