  "apiErrors.notFound.voiceNoteFound": "Sesli not bulunamadı.",
  "apiErrors.invalidValue.sendVoiceRecording": "En fazla birkaç dakikalık bir ses kaydı gönderin.",
  "apiErrors.invalidValue.recordingNotPrepared": "Bu kayıt hazırlanamadı — lütfen yeniden kaydedin.",
  "training.lessons.messages-private.step5": "Sesli not da gönderebilirsiniz: mesaj kutusunun yanındaki mikrofona dokunun, konuşun ve durdura dokunun. Önce dinleyin — sonra gönderin ya da silip yeniden kaydedin. Biri size gönderdiğinde, gerçek sesini duymak için oynata dokunun.",
  "training.lessons.owner-messages-oversight.step5": "Okundu işaretleri: bir ekip üyesi ona gönderdiğiniz mesajı okuduğunda, okundu olarak işaretlendiğini görürsünüz. Personel ve yöneticiler birbirlerinin okundu işaretlerini aynı şekilde, her iki yönde görür.",
  "training.lessons.owner-messages-oversight.step6": "Kendi okumanız görünmezdir. Bir personelin size gönderdiği mesajı okuduğunuzda, o kişi asla bir okundu işareti görmez — ve ekibinize konuşmalarının uygulamada saklandığını ve sahibi olarak sizin onları okuyabildiğinizi söylemek zorunda değilsiniz. Bu gözetim, mağazanıza sahip çıkmanın bir parçasıdır.",
  "training.lessons.owner-messages-oversight.step7": "Personel arasındaki olumsuz mesajlar hakkında ne yapacağınız size kalmış. Görmezden gelin, biriyle sessizce konuşun ya da harekete geçin — seçim sizin, ve nerede gördüğünüzü asla söylemek zorunda değilsiniz.",
  "staffLib.perm.returnsComplete": "İadeleri ve değişimleri tamamlama",
  "staffLib.area.returnsAccess": "İade onayı",
  "staff.memberDialog.returnsAccessHint": "Bu işaretle bu kişi bir iadeyi onaylayıp para iadesini veya değişimi tamamlayabilir. İşaret yoksa, başlattığı iade işletme sahibini ya da onaylanmış bir ekip üyesini bekler.",
  "returns.waitingApproval": "İşletme sahibinden ya da onaylanmış bir ekip üyesinden onay bekleniyor.",
  "returns.waitingToFinish": "Onaylandı — işletme sahibi ya da onaylanmış bir ekip üyesi bu iadeyi tamamlayacak.",
