  "settings.policies.title": "Mağazanızın politikaları ve şartları",
  "settings.policies.ownerDescription": "Sizin mağazanız, sizin kurallarınız. Mağazanızın politikalarını ve şartlar ve koşullarınızı buraya yazın — yazarak girin ya da bir dosya yükleyin. Ekibin her yeni üyesi bunları başladığında bir kez görür ve ekibinizin tamamı bunları burada dilediği zaman okuyabilir. Bunları yalnızca siz değiştirebilirsiniz.",
  "settings.policies.memberDescription": "Mağazanızın kendi politikaları ve şartları, sahibi tarafından yazılmıştır. Bunları yalnızca sahibi değiştirebilir.",
