  "settings.platformPolicies.title": "Luminous StockHaven politikaları",
  "settings.platformPolicies.description": "Uygulamanın kendi şartları ve politikaları. Uygulamayla kalırlar ve ekipteki herkes bunları burada okuyabilir.",
  "staffWelcome.policiesIntro": "Başlamadan önce: mağazanızın politikaları ve şartları, sahibi tarafından yazılmıştır.",
  "plansLib.includes.storePolicies": "Ayarlar içinde kendi mağaza politikalarınız ve şartlarınız, tüm ekibinizin okuması için",
  "apiErrors.businessPoliciesOwnerOnly": "Bu mağazanın politikalarını ve şartlarını yalnızca sahibi değiştirebilir.",
  "apiErrors.policyFileInvalid": "25 MB altında bir PDF, metin, Word veya OpenDocument dosyası gönderin.",
  "apiErrors.policyTextTooLong": "Bu belge buraya yazmak için çok uzun. Bunun yerine dosya olarak yükleyebilirsiniz.",
  "training.lessons.owner-store-policies.title": "Mağazanızın politikaları ve şartları",
  "training.lessons.owner-store-policies.step1": "Ayarlar’ı açın ve Mağaza politikaları ve şartları kartını bulun. İki belge barındırır: Mağaza Politikalarınız — mağazanızın ev kuralları — ve Şartlar ve Koşullarınız.",
  "training.lessons.owner-store-policies.step2": "Her belge oraya yazılabilir ya da dosya olarak yüklenebilir (PDF, metin, Word veya OpenDocument, en fazla 25 MB). İkisinden biridir: metni kaydetmek bir dosyanın yerini alır, dosya yüklemek metnin yerini alır. Bir belgeyi kaldırmak onu temizler.",
  "training.lessons.owner-store-policies.step3": "Ekibiniz her iki belgeyi de bir kez, ilk başlangıçlarında karşılama sayfalarında görür ve bunları kendi Ayarlar’ında diledikleri zaman okuyabilir. Ekibiniz için salt okunurdurlar — bunları yalnızca siz yazabilir veya değiştirebilirsiniz.",
  "training.lessons.owner-store-policies.step4": "Her işletme kendi belgelerini saklar: buraya yazdıklarınız yalnızca bu mağazaya aittir ve başka bir işletmede asla görünmez. Luminous StockHaven’ın kendi şartları ve politikaları Ayarlar’da sizinkilerin yanında yaşar ve onları da herkes okuyabilir.",
  "training.lessons.welcome-basics.step5": "Mağazanızın politikaları ve şartları karşılama sayfanızda bir kez gösterilir ve Ayarlar’da yaşar; orada bunları dilediğiniz zaman okuyabilirsiniz.",
  "apiErrors.policyDocNotFound": "Bu belge ikisinden biri değil.",
  "apiErrors.policyFileNotFound": "Bu belge için kaydedilmiş bir dosya yok.",
  "staffLib.perm.staffRoster": "Personel listesinin tamamını gör",
  "staffLib.area.staffAccess": "Personel listesi",
  "staff.memberDialog.staffAccessHint": "Yalnızca yöneticiler — bu işaretle bu yönetici, personel listesinin tamamını salt okunur olarak görebilir. İşaret yoksa bir yönetici yalnızca kendi kartını görür. Bu işaret personel için hiçbir şey yapmaz.",
