  "staffLib.perm.productsReorder": "Yeniden sipariş noktalarını değiştir",
  "staffLib.area.lowStockAccess": "Düşük stok",
  "staff.memberDialog.lowStockAccessHint": "İlk işaretle bu kişi düşük stok uyarılarını görür — İlgi gerekiyor kutusu, Düşük stok sayfası ve düşük seviye işaretleri. İkinci işaretle bir ürünün yeniden sipariş noktasını değiştirebilir; işaret yoksa Yeniden sipariş noktası kutusu görünmeye devam eder, ancak üzerinde yapılan değişiklik kaydedilmez.",
  "apiErrors.reorderChangeReserved": "Bir yeniden sipariş noktasını yalnızca işletme sahibi, ya da yeniden sipariş noktalarını değiştirmesine işletme sahibinin izin verdiği bir ekip üyesi değiştirebilir.",
  "apiErrors.alertsViewReserved": "Düşük stok uyarılarını yalnızca işletme sahibi, ya da düşük stok uyarılarını görmesine işletme sahibinin izin verdiği bir ekip üyesi görebilir.",
  "apiErrors.quizRequired": "Bu ders kısa bir sınavla biter — dersi tamamlamak için doğru cevaplayın.",
  "apiErrors.trainingIncomplete": "Henüz değil — bu kişinin hâlâ bitirmesi gereken eğitimi var.",
  "settings.policyQuiz.addMc": "Çoktan seçmeli soru ekle",
