  "settings.policyQuiz.expected": "Beklenen cevap",
  "settings.policyQuiz.expectedHint": "Beklediğiniz cevap, kendi sözlerinizle. Neredeyse kelimesi kelimesine uyan bir cevap yerinde doğru sayılır; geri kalanlar bakmanız için size gelir.",
  "settings.policyQuiz.hint": "Ekibiniz için bu belge hakkında sorular yazın. Bir kişi, Personel kaydında bu eğitimi onun için işaretlediğinizde Eğitim'de bunları cevaplar. Yazabileceğiniz soru sayısında sınır yoktur.",
  "settings.policyQuiz.mcLabel": "Çoktan seçmeli",
