  "settings.policyQuiz.passLineHint": "Bir kişinin bu eğitimi bitirmesi için gereken puan — yalnızca çoktan seçmeli cevaplar sayılarak.",
  "settings.policyQuiz.question": "Soru",
  "settings.policyQuiz.remove": "Kaldır",
  "settings.policyQuiz.save": "Soruları kaydet",
  "settings.policyQuiz.saved": "Sorular kaydedildi.",
  "settings.policyQuiz.title": "Ekibiniz için sorular",
  "staff.memberDialog.trainingAccessHint": "Mağaza politikalarını ve şartlarını okumak herkes içindir. Bu işaretler, sahibin Ayarlar'da her belgenin yanında oluşturduğu sınav eğitimlerini atar.",
  "staffLib.area.trainingAccess": "Politika sınav eğitimleri",
  "staffLib.perm.trainingPoliciesQuiz": "Mağaza Politikaları sınav eğitimi",
  "staffLib.perm.trainingTermsQuiz": "Şartlar ve Koşullar sınav eğitimi",
  "training.comment.placeholder": "Bu ders hakkında bir şeyler…",
  "training.comment.send": "Yorumu gönder",
  "training.comment.sent": "Yorumunuz sahibine iletildi.",
  "training.comment.title": "Sahibi için bir yorum bırakın",
  "training.lessons.download-app.step1": "Luminous StockHaven telefonunuzda veya bilgisayarınızda gerçek bir uygulama gibi yaşayabilir — uygulama mağazası gerekmez.",
  "training.lessons.download-app.step2": "Ayarlar'ı açın ve Uygulamayı indir kartını bulun. Her rol için, her iki planda da oradadır.",
  "training.lessons.download-app.step3": "Kur düğmesine dokunun ve cihazınızın yönergesini izleyin. Uygulama, mağazanın adı ve simgesiyle ana ekranınıza gelir.",
  "training.lessons.download-app.step4": "O andan sonra onu ana ekranınızdan açın — aynı şekilde oturum açar ve aynı mağazayı gösterir.",
  "training.lessons.download-app.title": "Uygulamayı cihazınıza indirin",
  "training.lessons.mgr-tax-rate.step1": "Siparişler bir satış vergisi oranı taşıyabilir. Oranın kendisini sahibi Ayarlar'da belirler; tüm mağaza için tek bir orandır.",
  "training.lessons.mgr-tax-rate.step2": "Sahibi, Personel kaydınızda vergi bölümünü sizin için işaretlediğinde, oran Ayarlar'ınızda da görünür ve onu orada güncel tutabilirsiniz.",
  "training.lessons.mgr-tax-rate.step3": "Oran bir yüzdedir — 8.25, müşterinin siparişin ürünlerinin üzerine 8.25% vergi ödediği anlamına gelir.",
  "training.lessons.mgr-tax-rate.step4": "Oran değiştiğinde, yeni siparişler yeni oranı kullanır. Zaten verilmiş siparişler, verildikleri oranı korur.",
  "training.lessons.mgr-tax-rate.step5": "Sahibi vergiyi Otomatik yaparsa, yeni bir sipariş, eyalet siparişe yazıldığı anda vergisini müşterinin eyalet temel oranıyla doldurur ve eyalet değişirse yeniden doldurur. Bunlar eyalet temel oranlarıdır; yerel vergiler eklenebilir. Eyaleti olmayan veya ABD dışından bir sipariş, mağazanın sabit oranını kullanır — ve bir siparişe yazılan vergi her zaman geçerli olur.",
  "training.lessons.mgr-tax-rate.title": "Mağazanın vergi oranı",
  "training.lessons.owner-confidentiality.step5": "İşte tüm harita. Ekibiniz kendi işini görür — kendi programını, görevlerini, maaş bordrolarını, mesajlarını ve rolünün açtığı mağaza ekranlarını. Denemenizi, işletmenin hangi planda olduğunu, planın ne kadara mal olduğunu, bir ödemenin geçip geçmediğini veya bir plan sınırına ulaşıldığını asla görmezler. Para yüzeyleri — faturalandırma, faturalar, ödeme yöntemleri — her zaman sadece sahibinindir.",
  "training.lessons.owner-confidentiality.step6": "Hesap bir gün durdurulursa, ekibinizin gördüğü tam mesaj şudur: “Değişiklikler şu anda kapalı. Şu anda hiçbir şey eklenemez veya değiştirilemez — bir şeye ihtiyacınız varsa işletme sahibine sorun.” İçinde hiçbir şey bir planı, fiyatı veya ödemeyi adlandırmaz.",
  "training.lessons.owner-confidentiality.step7": "Ve bir plan sınırı bir şeyi durdurduğunda, tam mesaj şudur: “Bu şu anda eklenemez — lütfen işletme sahibine sorun.” Bir sınıra ulaşıldığını asla söylemez — bu sizinle uygulama arasında kalır.",
  "training.lessons.staff-builds.step1": "Bir yapım, ürünleri satılabilir tek bir şeyde bir araya getirir — bir paket, bir kit, bir hediye seti. Yapımlar menüdeki Yapımlar ekranında yaşar.",
  "training.lessons.staff-builds.step2": "Neyin girdiğini görmek için bir yapımı açın: her parça ürün ve yapımın her birinden kaç tane kullandığı.",
  "training.lessons.staff-builds.step3": "Bir yapım yapıldığında veya satıldığında, parçalarının stoğu onunla birlikte hareket eder — uygulama sayımları sizin için dürüst tutar.",
  "training.lessons.staff-builds.step4": "Bir parça eksikse veya bir sayım yanlış görünüyorsa, tahmin etmek yerine yöneticinize söyleyin — yapımlar aynı anda birçok ürüne dokunur.",
  "training.lessons.staff-builds.title": "Yapımlar ve paketler",
  "training.lessons.staff-cross-store.step1": "İşletmenizin birden fazla mağazası veya sitesi olduğunda, mağazalar birbirlerinden stok isteyebilir. Bu istekler mağazalar arası gelen kutusuna düşer.",
  "training.lessons.staff-cross-store.step2": "Başka bir mağazanın ne istediğini ve mağazanıza ne gönderildiğini görmek için gelen kutusunu menüden açın.",
  "training.lessons.staff-cross-store.step3": "Bir isteğe yalnızca yöneticinizin size gösterdiği şekilde cevap verin — stok göndermek kendi mağazanızın sayımlarını değiştirir.",
  "training.lessons.staff-cross-store.step4": "Bir istek yanlış görünüyorsa — yanlış ürün veya sahip olduğunuzdan fazlası — tahmin etmeyin. Yöneticinize bildirin.",
  "training.lessons.staff-cross-store.title": "Mağazalar arası gelen kutusu",
  "training.lessons.staff-reports.step1": "Raporlar mağazanın sayılarını — satışlar, stok ve daha fazlası — tek bir yerde toplar. Raporlar menüde yaşar.",
  "training.lessons.staff-reports.step2": "Kapsadığı tarihler için sayılarını görmek üzere bir raporu açın. Tarihler raporun bir parçasıdır: aynı rapor farklı bir haftada farklı bir hikâye anlatır.",
  "training.lessons.staff-reports.step3": "Bazı raporlar uygulama dışına dosya olarak kaydedilebilir. Bir raporu yalnızca yöneticiniz veya sahibi istediğinde dışarı kaydedin.",
  "training.lessons.staff-reports.step4": "Rapor sayıları mağazanın gerçek işinden gelir — siparişler, sayımlar ve hareketler — bu yüzden her yerde dürüst girişler raporları doğru tutar.",
  "training.lessons.staff-reports.title": "Raporları okumak",
  "training.lessons.welcome-basics.step6": "Bitirdiğinizde oturumu kapatın: her sayfanın en altında, telif hakkı satırının hemen üstünde bir Oturumu kapat bağlantısı bulunur. Oturumu kapatmak sizi her yerde, her cihazda kapatır — böylece kimse paylaşılan bir ekranda hesabınıza giremez.",
  "training.policy.belowLine": "Bu çizginin altında — bir kez daha deneyin.",
