  "training.lessons.your-profile-photo.title": "Profil fotoğrafınız",
  "training.lessons.your-profile-photo.step1": "Fotoğrafınız, uygulamanın üst kısmında adınızın yanında, Personel sayfasında ve mesajlarınızın yanında görünür — sahibi onayladıktan sonra. O zamana kadar yalnızca baş harfleriniz gösterilir.",
  "training.lessons.your-profile-photo.step2": "Ayarlar'ı açın ve Profil fotoğrafınız bölümünü bulun. Kendinize ait bir fotoğraf seçin ve gönderin. Onay için sahibine gider — beklerken hiçbir yerde görünmez.",
  "training.lessons.your-profile-photo.step3": "Sahibi onayladığında ziliniz çalar ve fotoğrafınız gösterilmeye başlar. Onaylanmazsa, farklı bir fotoğraf seçin ve onun yerine onu gönderin.",
  "training.lessons.your-profile-photo.step4": "Fotoğrafınızı değiştirmek de aynı şekilde çalışır: yenisi onay bekler ve mevcut fotoğrafınız yenisi onaylanana kadar yerinde kalır. Bir değişiklik onaylanmazsa, diğer fotoğrafınızı korursunuz.",
  "training.lessons.owner-profile-photos.title": "Profil fotoğrafları ve adınız",
  "training.lessons.owner-profile-photos.step1": "Herkesin fotoğrafı, uygulamanın üst kısmında adının yanında, Personel sayfanızda ve mesajlarının yanında gösterilir. Bir ekip üyesinin fotoğrafı, siz onaylayana kadar hiçbir yerde görünmez — onay yalnızca size aittir ve kimse kendi fotoğrafını onaylayamaz.",
  "training.lessons.owner-profile-photos.step2": "Birisi bir fotoğraf gönderdiğinde ziliniz çalar. Görmek için Personel sayfasını açın, ardından Onayla veya Onaylama seçeneğini seçin. Onaylamazsanız, kişiye başka bir fotoğraf seçmesi söylenir.",
  "training.lessons.owner-profile-photos.step3": "Bir kişi fotoğrafını değiştirirse, yenisi de aynı şekilde onayınızı bekler. Mevcut fotoğrafı beklerken yerinde kalır — ve değişikliği onaylamazsanız da kalır.",
  "training.lessons.owner-profile-photos.step4": "Kendi fotoğrafınızın onaya ihtiyacı yoktur: Ayarlar'da, Profil fotoğrafınız altında ayarlayın. Aynı kart adınızı da barındırır — oraya belirlediğiniz ad, ekibinizin gördüğü her yerde, uygulamada ve Mesajlar'da Sahibi kelimesinin yerini alır.",
  "payroll.dd.corrected": "Düzeltilmiş form",
  "payroll.dd.correctedDone": "Düzeltilmiş bilgileriniz sahibine gönderildi.",
  "payroll.dd.correctionNotice": "Sahibi, düzeltmeniz için formunuzu size geri gönderdi. Her rakamı kontrol ediniz, imzalayınız ve tekrar gönderiniz.",
