  "payroll.dd.fixHelp": "Bir rakam yanlışsa bilgilerinizi düzeltiniz ve formu tekrar gönderiniz. Yeni imzalı formunuz eskisinin yerini alır ve sahibine düzeltildiği bildirilir.",
