  "payroll.dd.signHelp": "Adınızı yazınız, ardından imzanızın nasıl görüneceğini seçiniz. Bu sizin elektronik imzanızdır — doğrudan hesaba yatırma formunuza tam olarak burada gösterildiği gibi yerleştirilir.",
