  "staffLib.area.clockAccess": "Zaman panosu ve çağrılar",
  "staff.memberDialog.clockAccessHint": "Yalnızca yöneticiler — iki ayrı işaret. Zaman panosu ve unutulan çıkışlar, bu yöneticinin ekibin zaman kayıtlarını görmesini ve Personel sayfasından zaman kayıtlarını düzeltmesini sağlar. Çağrılar, bu yöneticinin çağrı pencereleri açmasını sağlar, birinin vardiyası yokken çalışmasına izin verir. Bu işaretler personel için hiçbir şey yapmaz.",
