  "apiErrors.clockAdmin.boardNotGranted": "Bunu yalnızca sahibi, ya da sahibin zaman panosunu ve unutulan çıkışları emanet ettiği bir yönetici yapabilir.",
  "apiErrors.clockAdmin.ownerOnlyForManager": "Bir yöneticinin çağrılarını ve zaman kayıtlarını yalnızca sahibi yönetebilir.",
  "apiErrors.clockFix.outBeforeIn": "Çıkış saati, giriş saatinden sonra olmalıdır.",
  "apiErrors.clockFix.breakOutside": "Mola saatleri, giriş ve çıkış saatleri arasında olmalıdır.",
  "apiErrors.clockFix.invalidTime": "Her saati geçerli bir tarih ve saat olarak gönderin.",
  "apiErrors.notFound.timeEntryFound": "Zaman kaydı bulunamadı.",
  "training.lessons.mgr-clock-callin.title": "Çağrılar ve saat düzeltmeleri",
  "training.lessons.mgr-clock-callin.step1": "Sahibi, bir yöneticiye iki ayrı işaret verebilir. Çağrılar ile bir personel için çağrı penceresi açabilir, Zaman panosu ve unutulan çıkışlar ile ekibin zaman panosunu görebilir ve Personel sayfasından zaman kayıtlarını düzeltebilirsiniz. Her işaret kendi başına çalışır — bir yönetici birine diğeri olmadan sahip olabilir.",
  "training.lessons.mgr-clock-callin.step2": "Bir çağrı penceresi, hiçbir vardiya kapsamadığında bir kişinin oturum açıp giriş yapmasını sağlar. Bunu Personel sayfasındaki Çağrılar ve kaçırılan çıkışlar kartından açın.",
  "training.lessons.mgr-clock-callin.step3": "Pencere, o kişi çıkış yapana kadar açık kalır — ardından olağan 10 dakikalık oturum kapatma süresi gelir — ya da siz veya sahibi daha erken kapatana kadar. Kendi kendine kapanmaz.",
  "training.lessons.mgr-clock-callin.step4": "Birisi çıkış yapmayı unuttuğunda, planlanan vardiya biter bitmez kaydı Personel sayfasında ve Bordroda işaretlenir ve siz ve sahibi bilgilendirilirsiniz. Kayıt, düzeltilene kadar saymaya devam eder.",
  "training.lessons.mgr-clock-callin.step5": "Kaydı Personel sayfasından düzeltin: girişi, çıkışı ve mola saatlerini ayarlayın. Bir yönetici yalnızca personelin kayıtlarını düzeltir — bir yöneticinin kendi kayıtlarını sahibi düzeltir.",
  "staffLib.perm.staffDocuments": "Personel belgeleri",
  "staffLib.area.documentsAccess": "Personel belgeleri",
  "staff.memberDialog.documentsAccessHint": "Yalnızca yöneticiler — bu işaretle bu yönetici, personel üyelerinin belge dosyalarını açabilir: her kişi için saklanan evraklar, örneğin W-4 formları, iş başvuruları ve kimlik kopyaları. Önce onaylamanız istenecek — bu dosyalarda Sosyal Güvenlik numaraları ve doğum tarihleri bulunur. Bu işaret personel için hiçbir şey yapmaz.",
  "staff.documentsWarning.body": "Bu kişi, personel üyeleriniz hakkındaki gizli bilgileri, Sosyal Güvenlik numaraları ve doğum tarihleri dahil, görebilecek.",
