  "plansLib.businessIncludes.xstoreMessages": "Mağazalar arası mesajlar — tüm ekibiniz, tüm işletmelerinizde",
  "xstore.title": "Mağazalar arası mesajlar",
  "xstore.help": "Bu hesaptaki herkes, tüm işletmelerinizde, tek bir gelen kutusunda. Buradan herhangi birine mesaj gönderin — yazılı veya sesli, teslim ve okundu işaretleriyle. Mağaza içi Mesajlar'ınız olduğu gibi kalır.",
  "xstore.empty": "Henüz sohbet yok. Yeni mesaj ile bir tane başlatın.",
  "xstore.noPeople": "Henüz mesaj gönderebileceğiniz başka kimse yok. Kişiler, işletmelerinizden birine katılıp oturum açtıklarında burada görünür.",
  "xstore.deliveredLabel": "Teslim edildi",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Mağazalar arası mesajlar, Business planının bir parçasıdır.",
  "apiErrors.invalidValue.personNotPartAccount": "O kişi bu hesabın bir parçası değil.",
  "training.lessons.owner-xstore-messages.title": "Mağazalarınız arasında mesajlar, işletme sahipleri için",
  "training.lessons.owner-xstore-messages.step1": "Mağazalar arası mesajlar, Mesajlar'dan ayrı ikinci bir gelen kutusudur. Mesajlar, bulunduğunuz mağaza içindir; bu kapı ise hesabınızdaki herkese, sahip olduğunuz her işletmede ulaşır — en fazla beş işletmeye kadar.",
  "training.lessons.owner-xstore-messages.step2": "Menüden Mağazalar arası mesajlar'ı açın ve listedeki herhangi biriyle sohbet başlatın. Liste, oturum açmış olan tüm işletmelerinizdeki her ekip üyesini, çalıştıkları mağazalarla birlikte gösterir.",
  "training.lessons.owner-xstore-messages.step3": "Fotoğraflar da birlikte gelir: her kişi onaylanmış profil fotoğrafını, yoksa adının baş harflerini gösterir. Her mesaj, gönderildiği tarih ve saati taşır.",
  "training.lessons.owner-xstore-messages.step4": "Kendi mesajlarınızın altında, bir mesaj ulaştığında Teslim edildi, diğer kişi sohbeti açtığında ise Okundu bilgisini görebilirsiniz. Sesli notlar burada da aynen Mesajlar'daki gibi çalışır.",
  "training.lessons.owner-xstore-messages.step5": "Buradaki sohbetler, içinde yer alan iki kişi için özeldir. Mağaza içi Mesajlar üzerindeki gözetiminiz mağazalar arasına ulaşmaz.",
  "training.lessons.mgr-xstore-messages.title": "Mağazalarınız arasında mesajlar, yöneticiler için",
  "training.lessons.mgr-xstore-messages.step1": "Mağazalar arası mesajlar, bu hesaptaki herkese, her işletmede ulaşır — yalnızca bulunduğunuz mağazaya değil. Menüde, Mesajlar'dan ayrı olarak yer alır.",
  "training.lessons.mgr-xstore-messages.step2": "Listeden bir sohbet başlatın: oturum açmış her ekip üyesi, adının yanında çalıştığı mağazalarla birlikte oradadır.",
  "training.lessons.mgr-xstore-messages.step3": "Yazılı gönderin veya sesli not kaydedin. Bir sesli not gönderilmeden önce onu dinleyebilir, atabilir veya gönderebilirsiniz — aynen Mesajlar'daki gibi.",
  "training.lessons.mgr-xstore-messages.step4": "Mesajlarınız ulaştığında Teslim edildi, diğer kişi sohbeti açtığında Okundu olarak görünür. Her adın yanındaki fotoğraf, o kişinin onaylanmış profil fotoğrafıdır.",
  "training.lessons.staff-xstore-messages.title": "Mağazalarınız arasında mesajlar",
  "training.lessons.staff-xstore-messages.step1": "Mağazalar arası mesajlar, bu hesaptaki herhangi birine, işletme sahibinin herhangi bir işletmesinde ulaşabileceğiniz yerdir — başka bir mağazaya sorulacak bir sorunun artık beklemesi gerekmez.",
  "training.lessons.staff-xstore-messages.step2": "Menüden açın, kişiyi seçin ve yazın. İhtiyacınız olan kişi listede yoksa, henüz oturum açmamış demektir — açar açmaz görünür.",
  "training.lessons.staff-xstore-messages.step3": "Burada sesli not da gönderebilirsiniz: kaydedin, dinleyin, sonra gönderin veya atın. Her mesaj, gönderildiği tarih ve saati gösterir.",
  "training.lessons.staff-xstore-messages.step4": "Bir mesaj gönderdiğinizde, ulaştığında Teslim edildi, diğer kişi sohbeti açtığında ise Okundu olarak görünür. Bir sohbet, siz ve diğer kişi için özeldir.",
