  "plansLib.businessIncludes.restaurantOps": "Restoran işlemleri — üç yönlü eşleştirmeli tedarikçi faturaları, atık kaydı, son kullanma tarihleri ve alerjen tablosu",
  "plansLib.businessIncludes.restaurantDaily": "Restoran günlük araçları — sıcaklık kayıtları, tükendi panosu, hazırlık sayfaları, menü mühendisliği, fark ve muhasebe dışa aktarımı",
  "plansLib.businessIncludes.restaurantKitchen": "Restoran, Mutfak ve tarifler — otomatik malzeme düşüşü ve gerçek yemek maliyetleriyle tarifler, hazırlık sayfaları, toplu üretim ve menü mühendisliği",
  "plansLib.businessIncludes.restaurantStock": "Restoran, Stok ve siparişler — par seviyeleri, tedarikçi sipariş rehberi ve şubeler arası transferler, ayrıca raf sırasına göre sayım sayfaları",
  "plansLib.businessIncludes.restaurantMoney": "Restoran, Faturalar ve para — üç yönlü eşleştirmeli tedarikçi faturaları, fiyat uyarıları, fark ve muhasebe dışa aktarımı, ayrıca tedarikçi kredi notları",
  "plansLib.businessIncludes.restaurantSafety": "Restoran, Gıda güvenliği — sıcaklık kayıtları, önce biten önce çıkar sırasıyla son kullanma tarihleri, tarih etiketleri ve alerjen tablosu, ve gıda güvenliği dosyası için doldurulmuş sıcaklık günlükleri",
