  "training.lessons.owner-restaurant-ops.title": "Restoran işlemleri, sahipler için",
  "training.lessons.owner-restaurant-ops.step1": "Tedarikçi faturaları Restoran köşesinde yaşar. Bir tedarikçinin fatura ettiğini, satın alma siparişine bağlı olarak girin; uygulama üç yönlü kontrol eder — sipariş edilen, teslim alınan ve fatura edilen yan yana — ve kısa, fazla veya farklı fiyattan fatura edilen her satırı işaretler.",
  "training.lessons.owner-restaurant-ops.step2": "Bir fatura satırı bir ürünü kayıttaki maliyetten farklı bir fiyattan fatura ettiğinde faturalar sayfasında bir fiyat uyarısı açılır. Bir uyarıyı kabul etmek ürünün maliyetini fatura edilen fiyata günceller; yoksaymak maliyeti olduğu gibi bırakır.",
  "training.lessons.owner-restaurant-ops.step3": "Atık kaydı, mutfağın attığı her şeyi bir nedenle kaydeder — bozulma, fazla üretim, hazırlık hatası, iade, dökülme veya diğer — ve kaydetmek stoğu raftan kendiliğinden alır. Son kullanma partileri ilk süresi dolan ilk çıkar sırasında listelenir, böylece en erken son kullanma tarihi önce kullanılır ve işaretlediğiniz partiler için tarih etiketleri yazdırabilirsiniz.",
  "training.lessons.owner-restaurant-ops.step4": "Alerjen tablosu, her yemeğin alerjenlerini tarifinin malzemelerinden, dokuz büyük alerjene karşı hesaplar, böylece bir misafirin sorusu hafızadan değil kayıttan yanıtlanır. Sıcaklık kayıtları, tükendi panosu ve personel yemekleri tüm ekibe açıktır — işaret gerekmez — çünkü günlük kayıt ancak herkes yapabildiğinde işler.",
  "training.lessons.owner-restaurant-ops.step5": "Menü mühendisliği her yemeği ne kadar sattığına ve ne kadar kazandırdığına göre yerleştirir: yıldızlar, beygirler, bilmeceler ve köpekler. Fark sayfası, tariflerin raftan çıkması gerektiğini söylediğini personel yemekleri, atık ve çıkan her şeyle karşılaştırır — geriye kalan açıklanmayandır. Muhasebe dışa aktarımı teslim alınan alımları, atığı, personel yemeklerini ve tarif tükenmesini defterleriniz için tek defterde toplar.",
  "training.lessons.staff-restaurant-daily.title": "Mutfağın günlük alışkanlıkları",
  "training.lessons.staff-restaurant-daily.step1": "Bir şey atıldığında aynı gün atık kaydına kaydedin: ne olduğu, ne kadar ve nedeni — bozulma, fazla üretim, hazırlık hatası, iade, dökülme veya diğer. Kaydetmek stoğu raftan kendiliğinden alır; stoğu ayrıca ayarlamazsınız.",
  "training.lessons.staff-restaurant-daily.step2": "Her buzdolabı, dondurucu ve sıcak tutma sıcaklığını kontrol ettikçe kaydedin. Kayıt adınızı ve zamanı tutar ve güvenli aralığın dışındaki her ölçümü işaretler — düzeltici işlem olarak bu konuda ne yaptığınızı yazın.",
  "training.lessons.staff-restaurant-daily.step3": "Tükendi panosu şu anda neyin bittiğidir. Bir ürün bittiği anda ekleyin, böylece tüm ekip aynı anda bilir ve geri geldiğinde kaldırın — pano kimin kaldırdığını ve ne zaman kaldırdığını tutar.",
  "training.lessons.staff-restaurant-daily.step4": "Ekip yemek yediğinde personel yemeği olarak kaydedin. Her yemek, yemeğini raftan alır ve yemeğin tarif malzemelerini bir satış gibi kullanır. Personel yemeği günün gerçek bir maliyetidir ve kayıtta olmalıdır.",
  "training.lessons.mgr-restaurant-invoices.title": "Faturalar, partiler ve parti çalışmaları",
  "training.lessons.mgr-restaurant-invoices.step1": "Sahip size Tarif oluşturma işaretini emanet etti; bu aynı zamanda mutfağın üretim işini de açar: tedarikçi faturaları, son kullanma partileri ve parti üretimi. Satırlarıyla bir tedarikçi faturası girin — ürün, miktar ve fatura edilen maliyet — ve varsa satın alma siparişine bağlayın.",
  "training.lessons.mgr-restaurant-invoices.step2": "Bir satın alma siparişi bağlıyken fatura üç yönlü, satır satır kontrol edilir: ne sipariş edildi, ne teslim alındı ve ne fatura edildi. Bir satır eşleşen, kısa, fazla, farklı fiyattan fatura edilmiş veya siparişte hiç olmayan olarak dönebilir.",
  "training.lessons.mgr-restaurant-invoices.step3": "Fatura edilen bir fiyat ürünün kayıttaki maliyetinden farklı olduğunda bir fiyat uyarısı açılır. Uyarıyı kabul etmek ürünün maliyetini yeni fatura edilen fiyata ayarlar; yoksaymak hiçbir şeyi değiştirmez. Aynı fatura ve ürün için aynı anda yalnızca bir açık uyarı bulunur.",
  "training.lessons.mgr-restaurant-invoices.step4": "Stoğu son kullanma tarihi olan bir parti olarak teslim alın; son kullanma sayfası partileri ilk süresi dolan ilk çıkar tutar. Bir parti çalışması bir tarifi belirli sayıda yapar: tarifin malzemelerini kullanır ve bitmiş hazırlık ürününü rafa koyar — tarif önce o hazırlık ürününe bağlı olmalıdır.",
  "training.lessons.mgr-restaurant-invoices.step5": "Bir tedarikçi bir faturaya karşılık para iade ettiğinde — hasarlı bir kasa, eksik teslimat, düzeltilmiş bir fiyat — bunu faturalar sayfasında, o faturaya karşılık bir kredi notu olarak kaydedin. Tedarikçi faturanın kendisinden gelir ve not, faturada hâlâ borç olana karşılık sayılır: fatura, uygulanan kredisini ve borç bakiyesini gösterir. Bir kredi, faturasını asla aşamaz ve bir notu iptal etmek, sayılmayı bırakırken onu kayıtta tutar. Notu kâğıt üzerinde gerektiğinde satırından yazdırın — yazdırılan sayfa, tedarikçinin kredisine ilişkin kendi kaydınızdır, tedarikçinin belgesi değildir.",
  "training.lessons.mgr-restaurant-reports.title": "Menü mühendisliği, fark ve defterler",
  "training.lessons.mgr-restaurant-reports.step1": "Sahip size Yemek parası işaretini emanet etti; bu aynı zamanda mutfağın para raporlarını da açar: menü mühendisliği, fark ve muhasebe dışa aktarımı. Bu rakamlar, tüm yemek parası gibi işletme içinde kalır.",
  "training.lessons.mgr-restaurant-reports.step2": "Menü mühendisliği her yemeği dönemde ne kadar sattığına ve ne kadar kazandırdığına göre yerleştirir. Yıldızlar iyi satar ve iyi kazanır; beygirler iyi satar ama az kazanır; bilmeceler iyi kazanır ama az satar; köpekler ikisini de yapmaz.",
  "training.lessons.mgr-restaurant-reports.step3": "Fark sayfası ürün başına çalışır: tariflerin raftan çıkması gerektiğini söylediği, personel yemekleri, atık ve diğer her stok çıkışının yanında. Geriye kalan açıklanmayandır — ve açıklanmayan, gidip açıklanacak sayıdır.",
  "training.lessons.mgr-restaurant-reports.step4": "Muhasebe dışa aktarımı mutfak için tek defterdir: teslim alınan alımlar, atık, personel yemekleri ve tarif tükenmesi, her satır tarihi, miktarı ve maliyetiyle, defterlerinizi tutan kişiye vermeye hazır.",
  "apiErrors.invalidReference.recipeMustBelongBusiness": "Tarif bu işletmeye ait olmalıdır.",
  "apiErrors.invalidReference.purchaseOrderMustBelongBusiness": "Satın alma siparişi bu işletmeye ait olmalıdır.",
  "apiErrors.batchNeedsProduct": "Bir parti çalışması, bağlı bir hazırlık ürünü olan bir tarif gerektirir.",
  "apiErrors.invoiceFileInvalid": "25 MB altında bir PDF veya resim dosyası gönderin.",
  "apiErrors.invoiceFileNotFound": "Bu fatura dosyası kayıtlı değil.",
  "apiErrors.invoiceFileNotGranted": "Fatura dosyasını yalnızca işletme sahibi veya tarifler ve faturalar oluşturma konusunda güvenilen bir ekip üyesi değiştirebilir.",
  "apiErrors.invoiceNotInBusiness": "Bu fatura bu işletmeye ait değil.",
