  "storefronts.ebayDesc": "eBay vitrininizi bir kez bağlayın. Bir ürün eBay'de satıldığında, sayısı burada kendiliğinden düşer ve satış hareketlerinize kaydedilir — tıpkı çıkışta taratılmış gibi. Satışlar yalnızca tek yönde akar: eBay'den uygulamaya.",
