  "print.pool.title": "Barkod oluştur",
  "print.pool.intro": "Ürünler var olmadan önce barkodlar oluşturun. Bunları yazdırın, kendi barkodu olmayan ürünlere yapıştırın; biri daha sonra tarandığında uygulama kodu tanır ve ürünü eklemeyi önerir.",
  "print.pool.countLabel": "Kaç barkoda ihtiyacınız var?",
  "print.pool.generate": "Oluştur",
  "print.pool.generating": "Oluşturuluyor…",
  "print.pool.minted": "Havuzunuza {count} yeni barkod eklendi.",
