  "print.pool.printNow": "Şimdi yazdır",
  "print.pool.savePdf": "PDF olarak kaydet",
  "print.pool.failed": "Bu barkodlar oluşturulamadı. Lütfen tekrar deneyin.",
  "scan.pool.title": "Kendi yazdırdığınız barkodlardan biri",
  "scan.pool.body": "Bu henüz mağazanızda bir ürün değil — önceden yazdırdığınız bir barkod. Bunu ürün olarak eklemek ister misiniz?",
  "plansLib.includes.barcodePool": "Barkod havuzu — barkodları önceden yazdırın, her ürünü barkodu tarandığında ekleyin",
  "training.lessons.owner-barcode-pool.title": "Barkodları ürünlerden önce yazdırmak",
  "training.lessons.owner-barcode-pool.step1": "Bazı ürünlerin kendi barkodu yoktur — el yapımı parçalar, kendi kitap çantalarınız, kendiniz yaptığınız veya bir araya getirdiğiniz her şey. Yazdır bölümünde Barkod oluştur kapısı, ürünler var olmadan önce kodlar oluşturur.",
  "training.lessons.owner-barcode-pool.step2": "Kaç tane gerektiğini söyleyin — sınır yok — uygulama da işletmenizin barkod havuzuna o kadar yeni kod basar. Bunlar yalnızca işletmenize aittir, asla iki kez verilmez ve oluşturulmaları ne ürün ne de stok yaratır.",
  "training.lessons.owner-barcode-pool.step3": "Oluşturuldukları anda seçin: şimdi etiket olarak yazdırın ya da daha sonra yazdırmak üzere PDF olarak kaydedin. Her iki durumda da kodlar havuzdadır ve yazdırılan etiketler havuzla tam olarak eşleşir.",
  "training.lessons.owner-barcode-pool.step4": "Her ürünü yaptıkça üzerine bir etiket yapıştırın. Kullanılmayan kodlar havuzda öylece bekler — acele yok ve süreleri dolmaz.",
  "training.lessons.owner-barcode-pool.step5": "Etiketli bir ürün daha sonra tarandığında uygulama kendi yazdırdığı kodu tanır ve kodu önceden doldurulmuş olarak ürünü eklemeyi önerir. Eklendikten sonra kod, o ürünün kodu olur ve diğerleri gibi taranır.",
  "apiErrors.poolOwnerMints": "Havuz için barkodları yalnızca işletme sahibi oluşturur.",
