  "apiErrors.checklistsManage": "Kontrol listesi şablonlarını yalnızca işletme sahibi, ya da sahibin kontrol listesi şablonları onayını verdiği kişi değiştirebilir.",
  "apiErrors.checklistProof": "Bu maddenin işaretlenmeden önce kanıtı gerekir.",
  "apiErrors.checklistName": "Kontrol listesine bir ad verin.",
  "apiErrors.checklistItems": "Kontrol listesine en az bir madde ekleyin.",
  "apiErrors.checklistUntick": "Bu maddeyi yalnızca işaretleyen kişi, bir yönetici veya işletme sahibi geri alabilir.",
  "training.lessons.staff-checklists.title": "Bir kontrol listesini çalışmak",
  "training.lessons.staff-checklists.step1": "Kontrol listeleri işletmenizin çalıştığı listelerdir — açılış, kapanış, temizlik ve sahibin kurduğu her şey. Onları Kontrol listeleri altında bulun: bugünün listeleri en üstte, işaretlenmeye hazır.",
  "training.lessons.staff-checklists.step2": "Bir maddeyi gerçekten yaptığınızda işaretleyin. Her işaret kimin yaptığını ve ne zaman yaptığını yazar, böylece sıradaki kişi — ve evdeki işletme sahibi — neyin yapıldığını ve neyin eksik olduğunu görür.",
  "training.lessons.staff-checklists.step3": "Bazı maddeler işaretlenmeden önce kanıt ister: bitmiş işin fotoğrafı, bir kodun taraması ya da yazılmış bir sıcaklık. Önce kanıtı ekleyin, sonra işaretleyin — kanıtsız madde işaretlenmez.",
  "training.lessons.staff-checklists.step4": "Bir şeyi yanlışlıkla mı işaretlediniz? Geri alın — ama yalnızca kendi işaretlerinizi. Bir yönetici veya işletme sahibi herkesinkini geri alabilir, çünkü işaret üzerinde ad olan bir kayıttır.",
  "training.lessons.staff-checklists.step5": "Bir kontrol listesini çalışmak için asla izne ihtiyacınız yok. Şablonları kurmak ve kime atanacaklarını seçmek işletme sahibinin işidir, ya da sahibin kontrol listesi şablonları onayını verdiği kişinin.",
