  "foodSafety.mock.intro": "Bir deneme denetimi başlatın ve kontrol ettikçe her noktayı Kontrol Listeleri sayfasında işaretleyin. Her işaret, kimin ve ne zaman kontrol ettiğini kaydeder — bulduklarınızı yol boyunca düzeltin, dosya da çalışmayı göstersin.",
  "foodSafety.mock.startButton": "Bugünün deneme denetimini başlat",
