  "foodSafety.mock.item1": "Buzdolapları, dondurucular ve sıcak tutma güvenli aralıklarında ve sıcaklık kaydı doldurulmuş.",
  "foodSafety.mock.item2": "Soğutma ve yeniden ısıtma kontrolleri kaydedilmiş, bir ölçümün ıskaladığı yerde düzeltici eylemle.",
