  "training.lessons.staff-food-safety.title": "Gıda güvenliği dosyasını tutmak",
  "training.lessons.staff-food-safety.step1": "Gıda güvenliği dosyası, Restoran Köşesi’nin Gıda Güvenliği rafında yaşar: sıcaklık kayıtları, soğutma, yeniden ısıtma ve dezenfektan kayıtları, sertifikalar, güvenlik bilgi formları ve denetim paketi.",
  "training.lessons.staff-food-safety.step2": "Aralık dışı bir ölçüm, notu ne yaptığınızı söyleyene kadar bitmiş değildir — yeniden soğuttunuz, yeniden ısıttınız, dezenfektanı yeniden yaptınız, attınız. Not yoksa kayıt da yok: giriş geçerli sayılmaz.",
  "training.lessons.staff-food-safety.step3": "Soğutma, yeniden ısıtma ve dezenfektan kontrollerini sıcaklıklar gibi kaydedin: neyi kontrol ettiniz, ölçüm ve ıskaladığında düzeltici eylem.",
  "training.lessons.staff-food-safety.step4": "Sertifikalar bitmeden önce uyarır. Sizinki uyardığında sahibine söyleyin — ve herkes güvenlik bilgi formlarını rafında her zaman okuyabilir.",
  "training.lessons.staff-food-safety.step5": "Bir denetimden önce — veya her zaman — deneme denetimini Gıda Güvenliği rafından çalıştırın ve denetime hazır paketi denetçinin tarihlerine göre yazdırın.",
