  "training.lessons.staff-equipment.title": "Ekipman kayıtları ve arıza bildirme",
  "training.lessons.staff-equipment.step1": "İşletmenizin her makinesinin Ekipman altında kendi sayfası var: ne zaman alındığı, garantisinin ne zaman bittiği, bakımını kimin yaptığı ve başına gelen her şey.",
