  "training.lessons.staff-equipment.step4": "Bakım görevlerinin — temizlik, kireç çözme, servis — tarihleri var. Ekipman sayfası neyin geldiğini ve neyin geciktiğini gösterir, böylece hiçbir şey sessizce kaçmaz.",
